// Helpers for the new + legacy schemas. Use these everywhere instead of
// reading raw fields, so a creator with one IG post or many cross-posts
// renders identically and `carousel: true` items can be excluded from CPM.
export function igItemViews(item) {
  return item.totalViews ?? item.views ?? 0;
}
export function igItemPosts(item) {
  if (item.posts) return item.posts;
  if (item.link) return [{ platform: "ig", views: item.views ?? 0, link: item.link }];
  return [];
}
